def trans(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    blocks=[]
    for r in range(h-1):
      for c in range(w-1):
        if grid[r][c]==grid[r+1][c]==grid[r][c+1]==grid[r+1][c+1]==2:
          blocks.append((r,c))
    for r,c in blocks:
      coords=[(r-1,c-1),(r-1,c+2),(r+2,c-1),(r+2,c+2)]
      colors=[grid[rr][cc] if 0<=rr<h and 0<=cc<w else 0 for rr,cc in coords]
      newcolors=[colors[2],colors[0],colors[3],colors[1]]
      dirs=[(-1,-1),(-1,1),(1,-1),(1,1)]
      for (rr,cc),col,(dr,dc) in zip(coords,newcolors,dirs):
        if not col or not(0<=rr<h and 0<=cc<w): continue
        x,y=rr,cc
        while 0<=x<h and 0<=y<w:
          if grid[x][y]==2: break
          out[x][y]=col
          x+=dr;y+=dc
    return out
